// WF09 v1 - Config + validación del payload del webhook.
//
// Config: base URL de EvoAPI y nombre de la instancia conectada al WhatsApp
// del SDR. Cambiar aquí si migramos de plan EvoAPI o reconectamos otra cuenta.
//
// Validación: campos obligatorios + normalización de teléfonos (sin '+', solo dígitos).
// Si algo falla devolvemos un error claro para que HubSpot lo capture en el log.

// Self-hosted Evolution API v2.2.3 en servidor propio (nexau).
// Auth: header 'apikey: <global_key>'. La credencial httpHeaderAuth en n8n debe
// llamarse 'EvoAPI Cion' y tener name=apikey + value=<global_key>.
const EVOAPI_BASE_URL = 'https://cioevolutionapiapp.nexau.es';
const EVOAPI_INSTANCE = 'Leon-Test';

const VIDEO_BY_SEGMENT = {
  genesis: 'https://privado.consultoria.io/nuestra-estrategia',
  mega:    'https://ia.consultoria.io/proceso-en-detalle',
};

function normalizePhone(raw) {
  if (!raw) return null;
  const digits = String(raw).replace(/\D/g, '');
  // E.164 sin '+'. Mínimo razonable: 8 dígitos. Si no, inválido.
  if (digits.length < 8) return null;
  return digits;
}

function fail(msg) {
  throw new Error('WF09 payload error: ' + msg);
}

const payload = $input.first().json.body || $input.first().json;

// Campos obligatorios
const required = ['lead_id', 'lead_name', 'lead_phone', 'lead_company', 'closer_name', 'closer_phone', 'meeting_url', 'meeting_at', 'segment'];
for (const k of required) {
  if (!payload[k]) fail('missing field ' + k);
}

const lead_phone = normalizePhone(payload.lead_phone);
const closer_phone = normalizePhone(payload.closer_phone);
if (!lead_phone) fail('lead_phone is not a valid E.164 number');
if (!closer_phone) fail('closer_phone is not a valid E.164 number');

const segment = String(payload.segment).toLowerCase();
if (!VIDEO_BY_SEGMENT[segment]) fail('segment must be genesis or mega, got ' + segment);
const video_url = VIDEO_BY_SEGMENT[segment];

const stakeholders = Array.isArray(payload.stakeholders) ? payload.stakeholders : [];
const stakeholder_phones = [];
for (const sh of stakeholders) {
  const p = normalizePhone(sh.phone);
  if (!p) fail('stakeholder phone invalid: ' + JSON.stringify(sh));
  stakeholder_phones.push(p);
}

// Formato del título: "<marca> x C.io - DD/MM/YYYY a las HHh" en hora Madrid.
const meetingDate = new Date(payload.meeting_at);
if (isNaN(meetingDate.getTime())) fail('meeting_at is not a valid ISO date');

const fmtMadridParts = new Intl.DateTimeFormat('es-ES', {
  timeZone: 'Europe/Madrid',
  day: '2-digit', month: '2-digit', year: 'numeric',
  hour: '2-digit', minute: '2-digit', hourCycle: 'h23',
}).formatToParts(meetingDate).reduce((acc, p) => { acc[p.type] = p.value; return acc; }, {});
const dateStr = `${fmtMadridParts.day}/${fmtMadridParts.month}/${fmtMadridParts.year}`;
const timeStr = `${fmtMadridParts.hour}:${fmtMadridParts.minute}`;
const hourLabel = fmtMadridParts.hour + 'h'; // p.ej. 18h
const group_subject = `${payload.lead_company} x C.io - ${dateStr} a las ${hourLabel}`;

return [{
  json: {
    config: {
      evoapi_base_url: EVOAPI_BASE_URL,
      evoapi_instance: EVOAPI_INSTANCE,
    },
    lead: {
      id: payload.lead_id,
      name: payload.lead_name,
      phone: lead_phone,
      company: payload.lead_company,
    },
    closer: {
      name: payload.closer_name,
      phone: closer_phone,
    },
    meeting: {
      url: payload.meeting_url,
      at_iso: payload.meeting_at,
      date_madrid: dateStr,
      time_madrid: timeStr,
    },
    segment,
    video_url,
    group_subject,
    participants: [closer_phone, lead_phone, ...stakeholder_phones],
  }
}];

// WF09 v1 - Crea el grupo y envía los 5 mensajes iniciales en orden.
//
// Para cada paso, si la API devuelve error lanzamos para que la ejecución de
// n8n quede como failed (más fácil de detectar en el panel) y la respuesta al
// webhook indique error.
//
// Mensajes (siguen literalmente el SOP):
//   1. Hola {LEAD}, {CLOSER}, os presento
//   2. {LEAD} es el fundador de {TIENDA}
//   3. {CLOSER} es uno de nuestros consultores expertos en ecommerce
//   4. Os dejo por aquí el enlace para la reunión: {LINK}
//   5. Por cierto, {LEAD}, te dejo por aquí el vídeo que te había comentado
//      para que puedas verlo antes de la llamada {VIDEO}
//
// Los vídeos van como texto (link con preview), NO como sendMedia: el SOP
// manda enlace, no archivo de vídeo (las URLs son landing pages, no .mp4).

const d = $input.first().json;
const { config, lead, closer, meeting, video_url, group_subject, participants } = d;
const BASE = config.evoapi_base_url;
const INSTANCE = config.evoapi_instance;

async function evoapi(path, body) {
  return await this.helpers.httpRequestWithAuthentication.call(
    this, 'httpHeaderAuth',
    {
      method: 'POST',
      url: BASE + path,
      body,
      json: true,
      timeout: 30000,
    }
  );
}

// Pequeño delay entre mensajes para no parecer un bot disparando todo en el
// mismo segundo (más natural y evita rate limits puntuales).
const sleep = (ms) => new Promise(r => setTimeout(r, ms));

// 1) Crear grupo
let createResp;
try {
  createResp = await evoapi.call(this, '/group/create/' + encodeURIComponent(INSTANCE), {
    subject: group_subject,
    participants,
  });
} catch (e) {
  throw new Error('create-group failed: ' + (e?.message || JSON.stringify(e)));
}

const groupJid = createResp?.groupJid || createResp?.id || createResp?.group?.id;
if (!groupJid) {
  throw new Error('create-group: no groupJid in response: ' + JSON.stringify(createResp));
}

async function sendText(text) {
  return await evoapi.call(this, '/message/sendText/' + encodeURIComponent(INSTANCE), {
    number: groupJid,
    text,
  });
}

const MESSAGES = [
  `Hola ${lead.name}, ${closer.name}, os presento`,
  `${lead.name} es el fundador de ${lead.company}`,
  `${closer.name} es uno de nuestros consultores expertos en ecommerce`,
  `Os dejo por aquí el enlace para la reunión: ${meeting.url}`,
  `Por cierto, ${lead.name}, te dejo por aquí el vídeo que te había comentado para que puedas verlo antes de la llamada ${video_url}`,
];

const sent = [];
for (let i = 0; i < MESSAGES.length; i++) {
  try {
    const resp = await sendText.call(this, MESSAGES[i]);
    sent.push({ index: i + 1, ok: true, message_id: resp?.key?.id || resp?.id || null });
  } catch (e) {
    sent.push({ index: i + 1, ok: false, error: e?.message || String(e) });
    // Continuamos enviando los siguientes mensajes — preferimos un grupo con
    // mensajes parciales a abortar y dejar al lead viendo el grupo vacío.
  }
  await sleep(2500);
}

return [{
  json: {
    ok: true,
    group_jid: groupJid,
    group_subject,
    lead_id: lead.id,
    meeting_at: meeting.at_iso,
    sent,
  }
}];
